[
  {
    "name": "sqlrag_retrieve",
    "description": "统一 TableRAG 检索接口。hybrid-search 使用完整 query，执行查询解析、Evidence/表/列/字段值/Join Graph 多路召回、融合、重排序、Join Graph 表补全并组装最终 NL2SQL 上下文。search-evidences、search-tables、search-columns、search-values 必须使用 queries 列表；每个元素是一个独立关键词或短语，服务端会并行执行单关键词 BM25/模糊/向量检索后融合。不能把多个关键词拼成一个元素。expand-join-graph 使用 table_names。",
    "parameters": {
      "properties": {
        "operation": {
          "description": "检索方法：hybrid-search=完整问题混合检索；search-evidences/tables/columns/values=对应单路关键词并行检索；expand-join-graph=按候选表扩展关联路径。",
          "enum": [
            "hybrid-search",
            "search-evidences",
            "search-tables",
            "search-columns",
            "search-values",
            "expand-join-graph"
          ],
          "type": "string",
          "default": "hybrid-search"
        },
        "query": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "仅用于 hybrid-search。填写完整自然语言问题，例如‘查询最近一个月华东区域销售额最高的客户’；不要用于 search-* 的关键词并行检索。"
        },
        "queries": {
          "anyOf": [
            {
              "items": {
                "type": "string"
              },
              "maxItems": 8,
              "minItems": 1,
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "仅用于 search-evidences/search-tables/search-columns/search-values。填写 1-8 个独立关键词或短语；每个元素分别并行执行一次单关键词 BM25/模糊/向量召回，再按 RRF 与关键词覆盖率去重融合。例如 [‘华东区域’, ‘销售额’, ‘客户’]。不要把完整问题或多个关键词合并到一个元素中。"
        },
        "evidence_top_k": {
          "default": 5,
          "type": "integer"
        },
        "table_top_k": {
          "default": 10,
          "type": "integer"
        },
        "column_top_k": {
          "default": 20,
          "type": "integer"
        },
        "value_top_k": {
          "default": 5,
          "type": "integer"
        },
        "join_max_hops": {
          "default": 2,
          "type": "integer"
        },
        "final_table_top_k": {
          "default": 10,
          "type": "integer"
        },
        "final_column_top_k": {
          "default": 20,
          "type": "integer"
        },
        "table_names": {
          "anyOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        },
        "column_names": {
          "anyOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        }
      },
      "type": "object"
    }
  }
]

